-- Table structure for table `jev`
--

DROP TABLE IF EXISTS `jev`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jev` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `funds_id` tinyint unsigned NOT NULL,
  `journals_id` tinyint unsigned NOT NULL,
  `trns_no` varchar(45) DEFAULT NULL,
  `jev_no` varchar(20) DEFAULT NULL,
  `date_entry` date NOT NULL,
  `ref_no` varchar(99) DEFAULT NULL,
  `payee` varchar(99) NOT NULL,
  `explanation` varchar(250) DEFAULT NULL,
  `is_approved` tinyint NOT NULL DEFAULT '0',
  `is_disapproved` tinyint NOT NULL DEFAULT '0',
  `is_cancelled` tinyint NOT NULL DEFAULT '0',
  `is_edited` tinyint NOT NULL DEFAULT '0',
  `remarks` varchar(250) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` tinyint unsigned NOT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` tinyint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_journal_voucher_funds1_idx` (`funds_id`),
  KEY `fk_journal_voucher_users1_idx` (`created_by`),
  KEY `fk_journal_voucher_users2_idx` (`updated_by`),
  KEY `fk_journal_entry_voucher_journals1_idx` (`journals_id`),
  CONSTRAINT `fk_jev_funds1` FOREIGN KEY (`funds_id`) REFERENCES `funds` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_jev_users1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_jev_users2` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_journal_entry_voucher_journals1` FOREIGN KEY (`journals_id`) REFERENCES `journals` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1557 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

