DROP TABLE IF EXISTS `jev_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jev_accounts` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `jev_id` int unsigned NOT NULL,
  `function_program_project_id` int unsigned DEFAULT NULL,
  `general_ledger_accounts_id` smallint unsigned NOT NULL,
  `subsidiary_ledger_accounts_id` smallint unsigned DEFAULT NULL,
  `obligation_no` varchar(15) NOT NULL,
  `is_deposit` tinyint DEFAULT NULL,
  `is_debit` tinyint NOT NULL,
