DROP TABLE IF EXISTS `subsidiary_ledger_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `subsidiary_ledger_accounts` (
  `id` smallint unsigned NOT NULL AUTO_INCREMENT,
  `funds_id` tinyint unsigned NOT NULL,
  `general_ledger_accounts_id` smallint unsigned NOT NULL,
  `sub_code` varchar(20) NOT NULL,
  `sub_name` varchar(99) NOT NULL,
  `address` varchar(99) NOT NULL,
  `contact_person` varchar(99) DEFAULT NULL,
  `contact` varchar(99) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_subsidiary_ledger_accounts_general_ledger_accounts1_idx` (`general_ledger_accounts_id`),
  KEY `fk_subsidiary_ledger_accounts_funds1_idx` (`funds_id`),
  CONSTRAINT `fk_subsidiary_ledger_accounts_funds1` FOREIGN KEY (`funds_id`) REFERENCES `funds` (`id`),
  CONSTRAINT `fk_subsidiary_ledger_accounts_general_ledger_accounts1` FOREIGN KEY (`general_ledger_accounts_id`) REFERENCES `general_ledger_accounts` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=578 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

